codeExamples.code:
-- Original clustering was by region; queries now filter by customer_id
ALTER TABLE sales.orders
CLUSTER BY (customer_id, order_date);

-- Future writes and subsequent OPTIMIZE apply the new layout
OPTIMIZE sales.orders;

-- To stop clustering entirely (keep data as-is)
-- ALTER TABLE sales.orders CLUSTER BY NONE;

-- Confirm the new clustering columns
DESCRIBE DETAIL sales.orders;
